SELECT status, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, SUM(CASE WHEN channel = 'mobile' THEN 1 ELSE 0 END) AS mobile_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(channel))) AS channel_values, COUNT(shipping_fee) AS shipping_fee_count FROM orders GROUP BY status, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END
